#!/bin/bash
# Prepare out/play: a folder to play the modded build in, separate from the
# installed game and from the test run directory (whose saves the tests reset).
#
# - the .app is copied from the build (re-run after each build to update it)
# - master.dat / critter.dat / patch000.dat / sound are linked read-only from
#   the installed game; nothing there is modified
# - data/SAVEGAME starts as a copy of the installed game's saves (only when
#   out/play has no saves yet, so your play saves are kept on re-runs)
# - data/hd links the HD art packs generated by tools/hd (run-dir copies)
# - fallout2.cfg: the repository's example config with HD on ("mixed" pack)
#   and the display settings below (written once; edit it freely afterwards)
#
# Usage: tools/dev/setup-play-dir.sh [--force-config]
#   FALLOUT2_DATA_DIR  installed game (default ~/Games/Fallout 2)
#   PLAY_WIDTH / PLAY_HEIGHT / PLAY_WINDOWED  (default 3440 / 1440 / 0 = fullscreen)

set -euo pipefail

REPO_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
GAME_DIR="${FALLOUT2_DATA_DIR:-$HOME/Games/Fallout 2}"
BUILD_DIR="${BUILD_DIR:-$REPO_DIR/out/build/macos}"
PLAY_DIR="$REPO_DIR/out/play"
APP="Fallout II Community Edition.app"

if [[ ! -d "$BUILD_DIR/$APP" ]]; then
    echo "error: build first ($BUILD_DIR/$APP missing)" >&2
    exit 1
fi

mkdir -p "$PLAY_DIR/data"
rm -rf "$PLAY_DIR/$APP"
cp -R "$BUILD_DIR/$APP" "$PLAY_DIR/"

for f in master.dat critter.dat patch000.dat sound; do
    ln -sfn "$GAME_DIR/$f" "$PLAY_DIR/$f"
done
ln -sfn "$REPO_DIR/files/f2_res.dat" "$PLAY_DIR/f2_res.dat"

if [[ ! -d "$PLAY_DIR/data/SAVEGAME" ]]; then
    cp -R "$GAME_DIR/data/SAVEGAME" "$PLAY_DIR/data/SAVEGAME"
    echo "copied saves from $GAME_DIR"
fi

mkdir -p "$PLAY_DIR/data/hd"
for pack in ai scripted; do
    if [[ -d "$BUILD_DIR/data/hd/$pack" ]]; then
        ln -sfn "$BUILD_DIR/data/hd/$pack" "$PLAY_DIR/data/hd/$pack"
    else
        echo "warning: HD pack '$pack' not generated yet (tools/hd); HD art falls back to the original" >&2
    fi
done

CFG="$PLAY_DIR/fallout2.cfg"
if [[ ! -f "$CFG" || "${1:-}" == "--force-config" ]]; then
    sed -e "s/^resolution_x=.*/resolution_x=${PLAY_WIDTH:-3440}/" \
        -e "s/^resolution_y=.*/resolution_y=${PLAY_HEIGHT:-1440}/" \
        -e 's/^scale=.*/scale=2/' \
        -e "s/^windowed=.*/windowed=${PLAY_WINDOWED:-0}/" \
        -e 's/^skip_opening_movies=.*/skip_opening_movies=1/' \
        -e 's/^show_script_messages=.*/show_script_messages=0/' \
        -e 's/^show_tile_num=.*/show_tile_num=0/' \
        -e 's/^output_map_data_info=.*/output_map_data_info=0/' \
        -e 's/^mode=log/mode=environment/' \
        "$REPO_DIR/files/fallout2.cfg" >"$CFG"
    echo "wrote $CFG"
fi

echo "ready: open \"$PLAY_DIR/$APP\""
